(function(){const root=document.documentElement;const live=document.getElementById('live');const toast=document.querySelector('.toast');function announce(msg){if(live){live.textContent=msg;}if(toast){toast.textContent=msg;toast.style.display='block';setTimeout(()=>toast.style.display='none',2200);}}function applyTheme(name){root.setAttribute('data-theme',name);localStorage.setItem('theme',name);announce('Tema:'+name);}function setShield(on){if(on){root.setAttribute('data-theme','shield');}else{const saved=localStorage.getItem('theme')||'light';root.setAttribute('data-theme',saved);}}document.querySelectorAll('[data-action="set-theme"]').forEach(btn=>{btn.addEventListener('click',()=>applyTheme(btn.dataset.value));});const shield=document.getElementById('toggle-shield');if(shield){shield.addEventListener('change',e=>setShield(e.target.checked));}applyTheme(localStorage.getItem('theme')||'light');const burger=document.getElementById('hamburger');const menu=document.querySelector('.menu');if(burger&&menu){burger.addEventListener('click',()=>{menu.classList.toggle('open');burger.setAttribute('aria-expanded',menu.classList.contains('open'));});}document.querySelectorAll('.submenu>a').forEach(a=>{a.addEventListener('keydown',(e)=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();const ul=a.parentElement.querySelector('ul');if(ul)ul.style.display=(ul.style.display==='block'?'none':'block');}});});document.querySelectorAll('form').forEach(form=>{form.addEventListener('submit',(e)=>{e.preventDefault();if(!form.checkValidity()){form.reportValidity();announce('Corrija os campos inválidos.');return;}announce('Formulário enviado(simulação).');form.reset();});});const openModal=document.querySelector('[data-open-modal]');const closeModal=document.querySelector('[data-close-modal]');const backdrop=document.querySelector('.modal-backdrop');if(openModal&&closeModal&&backdrop){openModal.addEventListener('click',()=>{backdrop.style.display='flex';openModal.blur();});closeModal.addEventListener('click',()=>{backdrop.style.display='none';closeModal.blur();});backdrop.addEventListener('click',(e)=>{if(e.target===backdrop)backdrop.style.display='none';});}const lazy=document.querySelectorAll('img[data-src]');const io=('IntersectionObserver' in window)?new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){const img=entry.target;img.src=img.dataset.src;img.removeAttribute('data-src');io.unobserve(img);}});}):null;lazy.forEach(img=>io?io.observe(img):(img.src=img.dataset.src));})();